+        );
+        if let Some(second) = second {
+            encoded.push(
+                TABLE[usize::from(
+                    ((second & 0b0000_1111) << 2) | (third.unwrap_or(0) >> 6),
+                )] as char,
+            );
+        } else {
+            encoded.push('=');
+        }
+        if let Some(third) = third {
+            encoded.push(TABLE[usize::from(third & 0b0011_1111)] as char);
+        } else {
+            encoded.push('=');
+        }
+
+        index += 3;
+    }
+    encoded
